  grindStone: k((r) => { const g = g0(); add(g, G.cylLow(), '#9a9080', 0, 0.2, 0, 0.6, 0.4, 0.6); add(g, G.cylLow(), '#8a8070', 0, 0.5, 0, 0.45, 0.2, 0.45); add(g, G.cylLow(), '#6d4c41', 0.3, 0.8, 0, 0.04, 0.5, 0.04); return g; }),
  basketPile: k((r) => { const g = g0(); for (let i = 0; i < 3; i++) { add(g, G.cylLow(), '#c8a165', r.range(-0.6, 0.6), 0.2, r.range(-0.6, 0.6), 0.3, 0.4, 0.3); } add(g, G.sphereLow(), '#e6c97a', 0, 0.45, 0, 0.25, 0.1, 0.25); return g; }),
  mudHouse: k((r, Pp) => house(r, { w: r.range(3, 4.5), d: r.range(3, 4.5), h: 2.4, wall: Pp.wall || '#c8a070', roof: Pp.roof || '#8a7a5a', type: 'flat', parapet: true })),
