  harvest: k((r) => { const g = g0(), ps = [0, 1, 2].map((i) => { const p = makePerson('farmer', r); p.position.set(i * 1.3 - 1.3, 0, 0); g.add(p); return p; }); CIV_KITS.wheatPatch.build(r).children.forEach((c) => g.add(c)); return anim(g, (q, t) => ps.forEach((p, i) => { p.userData.parts.armR.rotation.x = -0.8 + Math.sin(t * 3 + i) * 0.7; p.userData.parts.body.rotation.x = 0.3; })); }),
  carvedRelief: k((r) => { const g = g0(); add(g, G.box(), '#c8b090', 0, 0.8, 0, 1.2, 1.6, 0.3); const fox = still(ANIMALS.fox(r)); fox.scale.setScalar(0.6); fox.position.set(0, 0.9, 0.2); fox.traverse((c) => { if (c.isMesh) c.material = MAT('#b8a080'); }); g.add(fox); return g; }),
  tPillar: k((r) => { const g = g0(), h = r.range(3, 5); add(g, G.box(), '#c8b090', 0, h / 2, 0, 0.5, h, 1.2); add(g, G.box(), '#c8b090', 0, h + 0.3, 0, 0.6, 0.6, 2.2); for (const sz of [-0.3, 0.3]) add(g, G.box(), '#a89070', 0.26, h * 0.6, sz, 0.02, 0.6, 0.12); const a = still(ANIMALS.fox(r)); a.scale.setScalar(0.5); a.traverse((c) => { if (c.isMesh) c.material = MAT('#a89070'); }); a.position.set(0.3, h * 0.4, 0); a.rotation.y = Math.PI / 2; g.add(a); return g; }),
