  ankhStatue: k((r) => { const g = g0(); add(g, G.box(), '#d8c090', 0, 0.3, 0, 0.8, 0.6, 0.8); add(g, G.box(), '#f4d03f', 0, 1.2, 0, 0.18, 1.2, 0.12); add(g, G.box(), '#f4d03f', 0, 1.55, 0, 0.8, 0.16, 0.12); add(g, new THREE.TorusGeometry(0.24, 0.07, 6, 14), '#f4d03f', 0, 2.0, 0, 1, 1.3, 1); return g; }),
