  sphinxSmall: k((r) => { const g = g0(); add(g, G.box(), '#d8bc80', 0, 0.4, 0, 1.6, 0.8, 3.4); add(g, G.sphereLow(), '#d8bc80', 0, 1.2, -0.4, 0.75, 0.7, 1.4); const p = still(makePerson('egyptPriest', r)); p.scale.setScalar(1.2); p.position.set(0, 0.8, 1.1); p.traverse((c) => { if (c.isMesh) c.material = MAT(c.material.color && c.material.color.getHexString() === 'f4d03f' ? '#f4d03f' : '#d8bc80'); }); g.add(p); for (const sx of [-1, 1]) add(g, G.box(), '#d8bc80', sx * 0.5, 0.25, 2.1, 0.4, 0.4, 1.2); return g; }),
